css:
.bk-otomo1 h2{font-size:1.27em; color:#fff; background:#1f4e79; padding:1.5mm 3mm; margin:0 0 3mm; border-radius:3px;}
.bk-otomo1 h3{font-size:1.09em; color:#1f4e79; border-left:4px solid #1f4e79; padding-left:2.5mm; margin:5mm 0 2mm;}
.bk-otomo1 p{margin:0 0 3mm;}
.bk-otomo1 .point{background:#fff6dd; border:1px solid #e8cf86; border-radius:3px; padding:2.5mm 3mm; margin:3mm 0; font-size:0.955em;}
.bk-otomo1 .point b{color:#a35a00;}
.bk-otomo1 .memo{background:#eef5ec; border:1px solid #b9d4b1; border-radius:3px; padding:2.5mm 3mm; margin:3mm 0; font-size:0.955em;}
.bk-otomo1 .memo b{color:#3a6b2c;}
.bk-otomo1 table{border-collapse:collapse; width:100%; font-size:0.864em; margin:2mm 0 3mm;}
.bk-otomo1 th,.bk-otomo1 td{border:1px solid #b8cce4; padding:1.2mm 1.5mm; vertical-align:top;}
.bk-otomo1 th{background:#dce6f1;}
.bk-otomo1 .small{font-size:0.818em; color:#666;}
.bk-otomo1 .time{float:right; font-size:0.773em; color:#cfe0f3; font-weight:normal;}
.bk-otomo1 .q{font-weight:bold; color:#1f4e79; margin-top:3mm;}
.bk-otomo1 .a{color:#555; font-size:0.909em;}
